  "heroglyph.flow.more.cause.d": "DOGYPT facilite la vie des amoureux des chiens, mais il rassemble aussi les gens de cœur et aide les chiens dans le besoin, en toute transparence. Même le fondateur de DOGYPT, HEKTHOR, vient d’un refuge.",
