  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. À l'intérieur de la meute : ce que voient les autres Membres",
  "privacy.s12.body": "L'article 3 décrit le GodsGrid public. À l'intérieur de la meute — la zone réservée aux membres — les autres Membres connectés voient davantage : votre prénom, votre numéro dogyptien, le nom et la photo de votre chien, les attributs que vous avez renseignés pour votre chien, les sorties que vous avez enregistrées ou annoncées, vos évaluations et commentaires, et tout ce que vous avez écrit sur votre profil. Ils ne voient pas votre adresse e-mail, votre adresse postale, vos données de paiement, ni vos messages avec qui que ce soit d'autre. Lorsque vous annoncez une sortie comme ouverte, l'itinéraire, la date et votre chien deviennent visibles pour chaque Membre afin qu'il puisse demander à se joindre — c'est ce que signifie l'annoncer. Une sortie que vous gardez privée n'est visible que par vous et par les personnes qui y participent déjà. Vous choisissez laquelle des deux options s'applique, et vous pouvez la modifier à tout moment.",
  "privacy.s13.title": "13. Messages et signalements",
  "privacy.s13.body": "Les messages privés entre Membres sont stockés dans notre base de données (Supabase) afin que les conversations survivent entre les sessions. Base légale : art. 6(1)(b) du RGPD — ils font partie de l'adhésion que vous avez payée. Nous ne les lisons pas de façon routinière et ne les utilisons jamais à des fins publicitaires ou de profilage. Nous n'ouvrons une conversation que lorsqu'elle est signalée, lorsque nous enquêtons sur un abus ou un incident de sécurité spécifique, ou lorsque la loi l'exige. Un signalement enregistre le motif que vous avez choisi, votre note facultative et une référence à ce que vous avez signalé — pas une copie distincte. Le blocage est enregistré comme une paire d'identifiants de membres. Si vous supprimez votre compte, vos messages disparaissent avec lui ; la copie dans le fil de l'autre personne reste, affichée comme venant d'un membre supprimé, car cette conversation lui appartient aussi.",
  "terms.s12.title": "12. Le contenu que vous publiez",
  "terms.s12.body": "En plus de votre HEROGLYPH, vous pouvez publier du contenu au sein de la meute : photos de sorties, itinéraires et lieux, descriptions de sorties, évaluations, commentaires et questions, et tout ce que vous écrivez sur votre profil. Lorsque vous marquez une sortie comme effectuée, les autres Membres voient votre prénom et les chiens qui l'ont faite avec vous. Vous restez propriétaire de tout ce que vous publiez. En le publiant, vous accordez à DOGYPT s.r.o. une licence mondiale, gratuite et non exclusive pour stocker, afficher et adapter ce contenu afin d'exploiter et de promouvoir le Service — par exemple en montrant votre photo de sortie sur la carte, dans une liste de sorties ou sur une carte de partage. La licence dure tant que le contenu est sur le Service ; elle prend fin si vous supprimez le contenu ou votre compte, à l'exception des sauvegardes, qui expirent selon leur cycle normal. Nous ne vendons pas votre contenu et ne le concédons sous licence à personne d'autre pour son propre usage. Ne publiez que ce que vous avez le droit de publier — y compris les photos prises par quelqu'un d'autre et les personnes reconnaissables sur celles-ci.",
  "terms.s13.title": "13. Messages entre Membres",
  "terms.s13.body": "Les Membres peuvent s'écrire directement. Les messages sont privés entre les participants — nous ne les lisons pas de façon routinière et ne les utilisons jamais à des fins publicitaires. Ils sont stockés sur nos serveurs afin que la conversation soit toujours là à votre retour, et nous pouvons lire une conversation dans trois cas : lorsque quelqu'un la signale, lorsque nous enquêtons sur un abus ou un incident de sécurité spécifique, ou lorsque la loi l'exige. Vous pouvez bloquer un autre Membre à tout moment ; le blocage est immédiat et s'applique dans les deux sens. Traitez les messages comme toute conversation en ligne — n'envoyez pas de données de paiement, de mots de passe ni de documents que vous ne voudriez pas voir stockés.",
  "terms.s14.title": "14. Signalement et modération",
  "terms.s14.body": "Les profils, les sorties et les conversations peuvent être signalés. Un signalement nous parvient et un être humain le lit — aujourd'hui c'est le fondateur, Matej Stacho. Nous visons à examiner chaque signalement dans un délai de 7 jours. Selon ce que nous constatons, nous pouvons ne rien faire, supprimer le contenu, avertir le Membre, limiter ce qu'il peut publier, ou fermer son compte. Si nous intervenons sur votre contenu, nous vous en expliquerons la raison par e-mail, et vous pourrez répondre et contester. Nous pouvons aussi supprimer du contenu de notre propre initiative lorsqu'il enfreint l'article 7. Un abus délibéré ou répété — harcèlement, spam, fausses sorties, contenu impliquant des mineurs — entraîne la fermeture du compte sans avertissement supplémentaire.",
