  "pack.cal.life.recSince": "depuis {year}",
  "pack.cal.life.tip.weight.title": "Rester mince est la seule chose prouvée",
  "pack.cal.life.tip.weight.body": "De tout ce que tu peux faire pour un chien, une chose a la preuve la plus solide sur l'espérance de vie : ne pas le laisser prendre du poids. La différence entre un chien mince et un chien légèrement en surpoids se compte en années, pas en mois. Tu dois pouvoir sentir les côtes sans appuyer.",
  "pack.cal.life.tip.move.title": "Du mouvement en vrai terrain, pas un tour du pâté de maisons",
  "pack.cal.life.tip.move.body": "Un terrain irrégulier maintient les articulations, les muscles et l'esprit actifs. Chaque sortie que tu enregistres devient une semaine foncée sur cette grille — et les semaines foncées sont la seule chose que tu peux vraiment influencer.",
  "pack.cal.life.tip.food.title": "Une nourriture que le chien reconnaît comme de la nourriture",
  "pack.cal.life.tip.food.body": "Moins il y a d'étapes entre l'ingrédient brut et la gamelle, moins de choses peuvent mal tourner en chemin. Les croquettes ne sont pas un péché, mais ce n'est pas non plus un régime — c'est un raccourci.",
  "pack.cal.life.tip.chem.title": "La chimie seulement quand c'est vraiment nécessaire",
  "pack.cal.life.tip.chem.body": "Les antiparasitaires toute l'année, l'anesthésie par confort et les antibiotiques « par précaution » sont des décisions, pas une routine. Demande-toi, pour chacun : que se passe-t-il si je ne le fais pas ? Partout où la réponse est « rien », ne le fais pas.",
  "pack.cal.life.tip.stress.title": "Le repos compte autant que le mouvement",
  "pack.cal.life.tip.stress.body": "Un chien toujours sur le qui-vive brûle son corps de l'intérieur. Un sommeil sans interruption, une journée prévisible et le calme après l'effort ne sont pas de la paresse — ce sont les heures que le corps passe à se réparer.",
  "pack.cal.life.tip.protocol.title": "Un protocole plutôt qu'une course panique chez le véto",
  "pack.cal.life.tip.protocol.body": "Le vermifuge, la coprologie et le bilan sanguin ont leurs propres fenêtres dans le calendrier. Un chien dont on vérifie le sang deux fois par an n'est pas soigné — il est maintenu à l'avance.",
  "pack.cal.life.tip.joints.title": "Les articulations sont traitées AVANT qu'elles commencent à faire mal",
  "pack.cal.life.tip.joints.body": "Ton chien est maintenant dans la tranche senior. La cure articulaire a sa fenêtre dans le calendrier à partir de novembre — pas parce qu'il boite, mais pour qu'il n'ait jamais à le faire.",
