  "pack.nature.bal.earth.deficiency.bruises": "Se fait des bleus facilement",
  "pack.nature.bal.earth.deficiency.muscle-tone": "Tonus musculaire faible",
  "pack.nature.bal.earth.deficiency.bleeding-gums": "Gencives qui saignent",
  "pack.nature.bal.earth.deficiency.swollen-abdomen": "Abdomen ou foie enflé",
