  "pack.nature.bal.metal.deficiency.bladder-weak": "Une vessie faible",
  "pack.nature.bal.metal.deficiency.moles-warts": "Grains de beauté et verrues",
  "pack.nature.bal.metal.deficiency.hair-loss": "Perte de poils",
