  "pack.nature.doc.footTitle": "QUI EST TON CHIEN",
  "pack.nature.intro.eyebrow": "Trois quiz courts, un seul document",
  "pack.nature.noDogs": "Ce quiz écrit son résultat sur la carte d'un chien, et il n'y a pas encore de chien sur ton compte.",
  "pack.nature.noDogsCta": "Retour à mes chiens",
  "pack.nature.result.again": "Refaire le quiz",
  "pack.nature.result.done": "Terminé",
  "pack.nature.intro.title": "Qui est ton chien ?",
  "pack.nature.intro.body": "Vingt-deux questions et une liste de contrôle. Tu découvres de quoi ton chien est fait, quel rôle il joue pour ta famille et de quel côté penche son équilibre en ce moment.",
  "pack.nature.intro.axis1": "Constitution",
  "pack.nature.intro.axis1sub": "Corps, tempérament et quoi lui donner à manger.",
  "pack.nature.intro.axis2": "Rôle dans la meute",
  "pack.nature.intro.axis2sub": "Son rôle dans la famille — et ce que tout le monde interprète mal.",
  "pack.nature.intro.axis3": "L'équilibre en ce moment",
  "pack.nature.intro.axis3sub": "La constitution est pour la vie. L'équilibre, lui, change.",
  "pack.nature.intro.cta": "Commencer",
  "pack.nature.part.element": "Corps",
  "pack.nature.part.role": "Meute",
  "pack.nature.question": "Question",
  "pack.nature.back": "Retour",
  "pack.nature.next": "Suivant",
  "pack.nature.toSpecial": "Continuer",
  "pack.nature.part.balance": "Équilibre",
  "pack.nature.balance.title": "Y a-t-il quelque chose en ce moment ?",
  "pack.nature.balance.body": "La constitution de ton chien est fixée pour la vie, mais elle peut basculer hors de l'équilibre. Coche tout ce qui s'applique — autant ou aussi peu que tu veux.",
  "pack.nature.balance.none": "Rien dans la liste ? Laisse-la vide et continue — c'est la meilleure réponse qui existe.",
  "pack.nature.progress": "Progression",
  "pack.nature.special.eyebrow": "Encore quatre — à la recherche de rôles spéciaux",
  "pack.nature.special.body": "Ces quatre rôles se superposent au rôle principal. La plupart des chiens n'en portent aucun — c'est normal.",
  "pack.nature.special.cta": "Afficher le résultat",
  "pack.nature.result.saved": "Enregistré sur la carte de ton chien",
  "pack.nature.result.savedAll": "Enregistré sur la carte de tous les chiens",
  "pack.nature.ans.yes": "Oui",
  "pack.nature.ans.sometimes": "Parfois",
  "pack.nature.ans.no": "Non",
  "pack.network.ads.body": "La publicité payante est un moyen très inefficace de trouver de nouveaux amoureux des chiens — et une façon de jeter notre argent aux grandes entreprises. C'est bien plus efficace de récompenser directement les membres du mouvement pour leur activité. Il y a un hic : <strong style=\"font-weight:600\">ça ne marche vraiment que si tu vas parler de nous aux gens autour de toi</strong> :)",
  "pack.network.ads.header": "Pourquoi cette méthode ?",
  "pack.network.ads.wordAd": "une publicité",
  "pack.network.ads.wordScroll": "un étranger fait défiler sans s'arrêter",
  "pack.network.allBones": "Tous les {n}",
  "pack.network.back": "Retour",
  "pack.network.bonesLabel": "Tes BONES",
  "pack.network.bonesRate": "{n} BONES = 1 €",
  "pack.network.bonesUnit": "bones",
  "pack.network.capHintLog": "Plafond 1:1 — un don ne peut qu'égaler ce que tu as déjà vécu.",
  "pack.network.capHintRow": "Plafond 1:1 — un don égale ce que tu as vécu",
  "pack.network.capped.none": "Aucune dévotion de ce don — tes dons égalent déjà tout ce que tu as vécu. Les BONES passent quand même. <i>L'argent double les années, il ne les remplace jamais.</i>",
  "pack.network.capped.room": "Plafonné à <b style=\"color:#2a1608\">{room}</b> — un don ne peut qu'égaler ce que tu as vécu ({lived} de dévotion jusqu'ici). Les BONES passent quand même ; l'honneur attend les jours.",
  "pack.network.chainFirstInvite": "ta première invitation",
  "pack.network.chainJoined": "{n} ont rejoint",
  "pack.network.chainWhoever": "qui qu'ils amènent",
  "pack.network.chainYou": "toi",
  "pack.network.close": "Fermer",
  "pack.network.confirmSend": "Tu es sûr ? Une fois envoyés, les BONES quittent ton solde — c'est irréversible.",
  "pack.network.copyLinkAria": "Copier le lien d'invitation",
  "pack.network.devotionWord": "dévotion",
  "pack.network.emptyLine": "Personne encore — le premier nom ici sera le début de ta ligne.",
  "pack.network.eyebrow": "DOGYPT grandit grâce à toi",
  "pack.network.generatingLink": "Génération de ton lien…",
  "pack.network.linkFailed": "Impossible de charger ton lien d'invitation.",
  "pack.network.linkRetry": "Réessayer",
  "pack.network.groupDirect": "directement",
  "pack.network.groupTheirBrings": "leurs invitations",
  "pack.network.inLine": "Dans ta ligne",
  "pack.network.info.bones.body": "Les BONES sont la monnaie interne de DOGYPT — un nom ludique pour une vraie chose. Un chien paie en os ; nous aussi. Tu les <b>gagnes</b> en amenant des amoureux des chiens dans la meute et en faisant avancer le mouvement, et tu les <b>dépenses</b> à l'intérieur de DOGYPT : en soutenant des collectes pour les refuges, en obtenant du merch, et plus tard en payant d'autres Dogyptiens pour ce qu'ils créent. <b>{n} BONES = 1 €.</b>",
  "pack.network.info.bones.cap": "Que sont les BONES ?",
  "pack.network.info.why.body": "Un mouvement de cette taille ne peut pas s'acheter — aucun budget n'atteint un étranger comme un Dogyptien atteint un ami. Alors la meute place la récompense là où est la portée : avec toi. Quand quelqu'un rejoint via ton lien, tu reçois <b>{l1} BONES</b> ; quand il amène quelqu'un à son tour, tu reçois <b>{l2}</b> de plus. Chaque Dogyptien qui passe le mot n'est pas un vendeur — c'est un missionnaire, et nous honorons ce travail.",
  "pack.network.info.why.cap": "Pourquoi nous te le demandons",
  "pack.network.intro": "Un mouvement ne grandit que quand ses membres portent le message et amènent de nouvelles personnes. Alors on te le demande directement : <strong style=\"color:#2a1608;font-weight:600\">invite les amoureux des chiens que tu connais</strong>. Voici exactement comment ça fonctionne.",
  "pack.network.inviteLinkHeader": "Ton lien d'invitation",
  "pack.network.listSummary": "{n} personnes · {b} BONES gagnés",
  "pack.network.noBonesYetHint": "Pas encore de BONES — invite quelqu'un d'abord.",
  "pack.network.noOneYet": "personne encore",
  "pack.network.openWallet": "Ouvrir le portefeuille",
  "pack.network.send.grow.lede": "Ceci finance ce que la meute construit ensuite.",
  "pack.network.send.grow.title": "Envoyer des BONES au mouvement",
  "pack.network.send.help.lede": "Va directement aux refuges et au sauvetage.",
