  "onepage.apps.dogid.lede": "Chaque détail sur ton chien au même endroit — la clé d’un suivi personnalisé par ton vétérinaire et AINUBIS.",
  "onepage.apps.dogtrip.lede": "Parcours des itinéraires vérifiés adaptés aux chiens et ajoute les tiens. Gagne des points et des badges pour votre vie active à deux.",
  "onepage.apps.sniffer.lede": "Une appli de rencontres pour les chiens et leurs humains. Trouve un copain, une bande ou un partenaire pour explorer le monde — comme une seule meute.",
  "onepage.apps.cause.name": "POUVOIR DE LA COMMUNAUTÉ",
  "onepage.apps.cause.lede": "Nous construisons DOGYPT ensemble par amour des chiens — 100 % transparent. Chaque membre voit toutes les recettes et dépenses.",
  "onepage.apps.ainubis.lede": "Notre mentor IA personnalisé qui connaît ton chien sur le bout des doigts — appuyé sur des livres vérifiés, des textes et de courts podcasts.",
