  "film.keepScrolling": "Continue de défiler",
  "onepage.hbook.0.title": "Il était une fois…",
  "onepage.hbook.0.glyph": "Le heroglyph de Hekthor",
  "onepage.hbook.0.sub": "Hekthor · chien n° 1",
  "onepage.hbook.0.cap": "Le miroir",
  "onepage.hbook.1.ini": "N",
  "onepage.hbook.1.lead": "é indésirable. Jeté dans une caisse, où il attendait la mort avec ses frères.",
  "onepage.hbook.1.txt": "Huit minuscules âmes se sont retrouvées dans un refuge. Sept d’entre elles ont trouvé un foyer. Un seul est resté — le plus grand, avec le plus grand tempérament. Un an plus tard, par pur hasard, il a rencontré Matej, qui n’avait jamais prévu d’avoir un chien. Une étincelle a jailli, et depuis juin 2017 ils marchent ensemble dans la vie.",
  "onepage.hbook.1.cap": "Huit dans une caisse",
  "onepage.hbook.2.ini": "I",
  "onepage.hbook.2.lead": "l a sauvé une vie humaine. Il est arrivé dans la saison la plus dure de celle-ci.",
  "onepage.hbook.2.txt": "Dans les moments les plus sombres, il a été l’ancre de Matej — il l’a tiré des pensées noires, de l’appartement, jusqu’à la nature. D’abord les rues voisines, puis les bois et les montagnes. Ils ont traversé toute la Slovaquie (820 km) et fait des road trips à travers l’Europe. L’aventure et la vie libre sur la route les ont liés.",
  "onepage.hbook.2.cap": "Du bureau au monde",
  "onepage.hbook.3.ini": "S",
  "onepage.hbook.3.lead": "a pure âme a fait naître la vision d’un mouvement mondial pour les amoureux des chiens.",
  "onepage.hbook.3.txt": "La vie avec un chien est le plus beau chapitre de la vie de chacun. Les gens de chiens sont une autre espèce de gens — ils résolvent sans cesse les mêmes problèmes précis, et leur amour des chiens les unit. Et si cette histoire devenait quelque chose d’utile ?",
  "onepage.hbook.3.cap": "Une vision naît",
  "onepage.hbook.4.ini": "D",
  "onepage.hbook.4.lead": "ix belles années derrière lui, et au moins dix autres devant !",
  "onepage.hbook.4.txt": "Hekthor a poussé Matej à tout apprendre sur les chiens — psychologie, dressage, sport et, surtout, longévité. Tout ce savoir servira à chacun dans DOGYPT : pas un énième réseau social à la mode, mais un réseau au contenu utile. Et tout ça grâce à un chien de refuge « ordinaire ».",
  "onepage.hbook.4.cap": "Fondateur n° 1",
  "onepage.hbook.5.ini": "A",
  "onepage.hbook.5.lead": "ujourd’hui, il vit en Slovaquie — dans les bois, les montagnes et près des lacs.",
  "onepage.hbook.5.txt": "Rapporter dans l’eau est son plus grand amour. Il est en pleine forme, sage, humble et le meilleur compagnon dont on puisse rêver. Quand nous ne sommes pas dehors, il veille à la maison sur deux matous, Gary et Yby, qu’il a sauvés de la rue.",
  "onepage.hbook.5.cap": "Gardien de la maison",
